package com.tekwatt.user.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="partners")public class Partner{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,length=160)private String companyName;@Column(nullable=false,length=120)private String contactName;@Column(length=190)private String email;@Column(length=32)private String phone;@Column(nullable=false,precision=5,scale=2)private BigDecimal commissionPercent;@Column(nullable=false,length=20)private String status;@Column(nullable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;protected Partner(){}public Partner(UUID t,String c,String n,String e,String p,BigDecimal commission){id=UUID.randomUUID();tenantId=t;update(c,n,e,p,commission,"ACTIVE");createdAt=updatedAt;}public void update(String c,String n,String e,String p,BigDecimal commission,String s){companyName=c;contactName=n;email=e;phone=p;commissionPercent=commission;status=s;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public String getCompanyName(){return companyName;}public String getContactName(){return contactName;}public String getEmail(){return email;}public String getPhone(){return phone;}public BigDecimal getCommissionPercent(){return commissionPercent;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
